// ═══ KOS INFRASTRUCTURE AUTO-SCALING ANALYZER ═══
const dockerRaw = $input.all()[0]?.json?.stdout || '';
const memUsage = parseFloat($input.all()[1]?.json?.stdout || '0');
const diskUsage = parseFloat($input.all()[2]?.json?.stdout || '0');

// Parse Docker stats
const containers = [];
if (dockerRaw.trim()) {
  const lines = dockerRaw.trim().split('\n');
  for (const line of lines) {
    try {
      const stats = JSON.parse(line);
      containers.push({
        name: stats.Name,
        cpu: parseFloat(stats.CPUPerc?.replace('%', '') || '0'),
        memory: parseFloat(stats.MemPerc?.replace('%', '') || '0'),
        memory_usage: stats.MemUsage?.split('/')[0]?.trim() || 'N/A',
        net_io: stats.NetIO || 'N/A'
      });
    } catch(e) { /* skip malformed lines */ }
  }
}

const now = new Date().toISOString();

// Thresholds
const CPU_CRITICAL = 85;
const MEM_CRITICAL = 85;
const MEM_WARNING = 70;
const DISK_CRITICAL = 90;

// Identify stressed containers
const stressed = containers.filter(c => c.cpu > CPU_CRITICAL || c.memory > MEM_CRITICAL);
const warnings = containers.filter(c => (c.cpu > 50 && c.cpu <= CPU_CRITICAL) || (c.memory > MEM_WARNING && c.memory <= MEM_CRITICAL));

const analysis = {
  timestamp: now,
  system: {
    memory_usage_percent: memUsage,
    disk_usage_percent: diskUsage,
    total_containers: containers.length
  },
  containers: containers,
  alerts: {
    critical: stressed,
    warnings: warnings,
    system_memory_critical: memUsage > MEM_CRITICAL,
    system_disk_critical: diskUsage > DISK_CRITICAL,
    action_required: stressed.length > 0 || memUsage > MEM_CRITICAL || diskUsage > DISK_CRITICAL
  },
  scaling_recommendations: []
};

// Generate scaling recommendations
if (stressed.length > 0) {
  for (const c of stressed) {
    analysis.scaling_recommendations.push({
      container: c.name,
      action: 'scale_up',
      reason: `CPU: ${c.cpu}% / Memory: ${c.memory}%`,
      priority: 'high'
    });
  }
}

if (analysis.alerts.system_memory_critical) {
  analysis.scaling_recommendations.push({
    container: 'host',
    action: 'alert_admin',
    reason: `System memory at ${memUsage}%`,
    priority: 'critical'
  });
}

if (analysis.alerts.system_disk_critical) {
  analysis.scaling_recommendations.push({
    container: 'host',
    action: 'cleanup_disk',
    reason: `Disk usage at ${diskUsage}%`,
    priority: 'critical'
  });
}

return analysis;

// ═══ EXECUTE SCALING ACTIONS ═══
const analysis = $input.all()[0]?.json;
const recs = analysis.scaling_recommendations || [];

// Filter high-priority actions
const urgent = recs.filter(r => r.priority === 'critical' || r.priority === 'high');

return {
  executed: urgent.length > 0,
  recommendations: urgent,
  timestamp: new Date().toISOString()
};

// ═══ NO-OP — System healthy ═══
return {
  timestamp: new Date().toISOString(),
  status: 'healthy',
  message: 'All systems nominal — no scaling needed.'
};
